import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

depthwise_conv2d_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void depthwise_conv2d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    const int batch_size,
    const int in_channels,
    const int input_height,
    const int input_width,
    const int kernel_h,
    const int kernel_w,
    const int output_height,
    const int output_width,
    const int stride_h,
    const int stride_w,
    const int padding_h,
    const int padding_w,
    const int dilation_h,
    const int dilation_w,
    const bool has_bias
) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_elements = batch_size * in_channels * output_height * output_width;
    if (idx >= total_elements) return;

    const int c = (idx / (output_height * output_width)) % in_channels;
    const int h_out = (idx / output_width) % output_height;
    const int w_out = idx % output_width;
    const int b = idx / (in_channels * output_height * output_width);

    const int h_in_start = h_out * stride_h - padding_h;
    const int w_in_start = w_out * stride_w - padding_w;

    float sum = 0.0f;

    for (int kh = 0; kh < kernel_h; ++kh) {
        const int h_in = h_in_start + kh * dilation_h;
        if (h_in < 0 || h_in >= input_height) continue;

        for (int kw = 0; kw < kernel_w; ++kw) {
            const int w_in = w_in_start + kw * dilation_w;
            if (w_in < 0 || w_in >= input_width) continue;

            const int input_idx = b * in_channels * input_height * input_width 
                                + c * input_height * input_width 
                                + h_in * input_width 
                                + w_in;

            const int weight_idx = c * kernel_h * kernel_w + kh * kernel_w + kw;
            sum += input[input_idx] * weight[weight_idx];
        }
    }

    if (has_bias) sum += bias[c];
    output[idx] = sum;
}

torch::Tensor depthwise_conv2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    bool has_bias
) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int input_height = input.size(2);
    const int input_width = input.size(3);
    const int kernel_h = weight.size(2);
    const int kernel_w = weight.size(3);

    const int output_height = (input_height + 2 * padding_h - dilation_h * (kernel_h - 1) - 1) / stride_h + 1;
    const int output_width = (input_width + 2 * padding_w - dilation_w * (kernel_w - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({batch_size, in_channels, output_height, output_width}, input.options());
    const int total_elements = output.numel();
    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    depthwise_conv2d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_height,
        input_width,
        kernel_h,
        kernel_w,
        output_height,
        output_width,
        stride_h,
        stride_w,
        padding_h,
        padding_w,
        dilation_h,
        dilation_w,
        has_bias
    );

    return output;
}
"""

depthwise_conv2d_cpp_source = """
torch::Tensor depthwise_conv2d_cuda_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride_h, int stride_w,
    int padding_h, int padding_w,
    int dilation_h, int dilation_w,
    bool has_bias
);
"""

depthwise_conv2d = load_inline(
    name='depthwise_conv2d',
    cpp_sources=depthwise_conv2d_cpp_source,
    cuda_sources=depthwise_conv2d_source,
    functions=['depthwise_conv2d_cuda_forward'],
    verbose=True
)

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size_h: int, kernel_size_w: int, 
                 stride_h: int = 1, stride_w: int = 1, padding_h: int = 0, padding_w: int = 0, 
                 dilation_h: int = 1, dilation_w: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        assert groups == in_channels, "Groups must equal in_channels for depthwise convolution"

        self.in_channels = in_channels
        self.kernel_size_h = kernel_size_h
        self.kernel_size_w = kernel_size_w
        self.stride_h = stride_h
        self.stride_w = stride_w
        self.padding_h = padding_h
        self.padding_w = padding_w
        self.dilation_h = dilation_h
        self.dilation_w = dilation_w
        self.has_bias = bias

        self.weight = nn.Parameter(torch.Tensor(in_channels, 1, kernel_size_h, kernel_size_w))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(in_channels))
        else:
            self.register_parameter('bias', None)

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in, _ = nn.init._calculate_fan_in_and_fan_out(self.weight)
            bound = 1 / math.sqrt(fan_in)
            nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        bias_tensor = self.bias if self.has_bias else torch.empty(0, device=x.device, dtype=x.dtype)
        return depthwise_conv2d.depthwise_conv2d_cuda_forward(
            x,
            self.weight,
            bias_tensor,
            self.stride_h,
            self.stride_w,
            self.padding_h,
            self.padding_w,
            self.dilation_h,
            self.dilation_w,
            self.has_bias
        )
